interface LayoutProps {
  children: React.ReactNode;
  params: Promise<{ tool?: string[] }>;
}

// Pass-through layout. All metadata for this route segment is generated by
// `src/app/[[...tool]]/page.tsx`'s `generateMetadata` (single source of truth).
// A duplicate `generateMetadata` here used to leak conflicting openGraph.url
// values and caused Next.js to drop page-level metadata; deleted in audit fix.
export default function ToolLayout({ children }: LayoutProps) {
  return <>{children}</>;
}
